import {
  MODDED_HERO_CLASSES,
  MODDED_GENERAL_TRINKETS,
  MODDED_GENERAL_TRINKET_MODS,
} from '../modded_heroes';
import { HERO_CLASSES } from '../heroes';
import { TRINKETS } from '../trinkets';
import { BACKER_TRINKETS } from '../backer_trinkets';
import { HERO_SPECIFIC_TRINKETS } from '../hero_specific_trinkets';
import { getTrinketImagePath } from '../../utils/imageHelper';
import { HERO_CONFIG } from '../../constants';

// `modded_heroes.js` is generated by `scripts/importModdedHeroes.js` from the
// workshop mods on disk. These pin the shape the app relies on, and the three
// facts the scraper it replaced got wrong: the kit order, `alwaysActive`, and
// which trinkets belong to a class.

const entries = Object.entries(MODDED_HERO_CLASSES);

describe('MODDED_HERO_CLASSES shape', () => {
  test('every class carries the fields the app reads', () => {
    const broken = entries.filter(([, d]) => !d.modId
      || !Array.isArray(d.skills)
      || !Array.isArray(d.campSkills)
      || !Array.isArray(d.vanillaCampSkills)
      || !Array.isArray(d.classSpecificTrinkets)
      || typeof d.image !== 'string');
    expect(broken.map(([n]) => n)).toEqual([]);
  });

  test('no name is blank or whitespace', () => {
    const blank = [];
    for (const [name, d] of entries) {
      for (const list of ['skills', 'campSkills', 'classSpecificTrinkets']) {
        for (const item of d[list] || []) if (!String(item).trim()) blank.push(`${name}.${list}`);
      }
    }
    expect(blank).toEqual([]);
  });

  test('every name is readable english', () => {
    // Forty of the installed mods ship their string tables in Chinese only.
    // `scripts/lib/moddedTranslations.js` covers them, and this is what says so:
    // a name that arrives here still in CJK means a mod was installed whose
    // strings nothing has translated yet, and the fix is to add them there
    // rather than to let the app show a name nobody can search for.
    const cjk = /[　-鿿가-힯぀-ヿ]/;
    const untranslated = [];
    for (const [name, d] of entries) {
      if (cjk.test(name)) untranslated.push(`class ${name}`);
      for (const list of ['skills', 'campSkills', 'classSpecificTrinkets']) {
        for (const item of d[list] || []) if (cjk.test(item)) untranslated.push(`${name}.${list}: ${item}`);
      }
    }
    for (const t of MODDED_GENERAL_TRINKETS) if (cjk.test(t)) untranslated.push(`general: ${t}`);
    expect(untranslated).toEqual([]);
  });

  test('a class never lists the same skill or trinket twice', () => {
    const dupes = [];
    for (const [name, d] of entries) {
      for (const list of ['skills', 'campSkills', 'classSpecificTrinkets']) {
        const items = d[list] || [];
        if (new Set(items).size !== items.length) dupes.push(`${name}.${list}`);
      }
    }
    expect(dupes).toEqual([]);
  });

  test('vanillaCampSkills is a subset of campSkills', () => {
    const stray = [];
    for (const [name, d] of entries) {
      const camp = new Set(d.campSkills || []);
      for (const v of d.vanillaCampSkills || []) if (!camp.has(v)) stray.push(`${name}: ${v}`);
    }
    expect(stray).toEqual([]);
  });

  test('vanillaCampSkills only names camp skills drawn from the vanilla art folder', () => {
    // `getCampSkillImagePath` sends anything listed here to
    // `/images/camp_skills/<name>.png`, so a mod's own label for a vanilla camp
    // skill ("Wounds Care" for `first_aid`, "Bénir" for `bless`) must not reach
    // this list - it would be a skill with no picture. `Hobby` is the one
    // vanilla camp skill no vanilla class carries: the game ships it, the art
    // folder has it, and a handful of mods hand it out.
    const vanilla = new Set(['Hobby']);
    for (const c of Object.values(HERO_CLASSES)) for (const s of c.campSkills || []) vanilla.add(s);
    const stray = [];
    for (const [name, d] of entries) {
      for (const v of d.vanillaCampSkills || []) if (!vanilla.has(v)) stray.push(`${name}: ${v}`);
    }
    expect(stray).toEqual([]);
  });

  test('the file is sorted by class name, so a re-import produces a readable diff', () => {
    const names = entries.map(([n]) => n);
    expect(names).toEqual([...names].sort((a, b) => a.localeCompare(b, 'en')));
  });
});

describe('always-active classes', () => {
  // `validateHero` uses `skills.length` as the required count for an
  // always-active hero, and `HeroConfiguration` fills `activeSkills` with the
  // whole list on class change. An empty kit would make the slot impossible to
  // complete.
  test('an always-active class has a kit to activate', () => {
    const empty = entries.filter(([, d]) => d.alwaysActive && !(d.skills || []).length);
    expect(empty.map(([n]) => n)).toEqual([]);
  });

  test('the flag is set on the classes that carry more skills than a hero may pick', () => {
    // Not every large kit is always-active - a mod may offer nine skills and
    // still let the player choose four - but a class the game marks
    // always-active is the only reason `activeSkills` may exceed MAX_SKILLS.
    const oversized = entries.filter(([, d]) => (d.skills || []).length > HERO_CONFIG.MAX_SKILLS);
    expect(oversized.length).toBeGreaterThan(0);
    expect(oversized.filter(([, d]) => d.alwaysActive).length).toBeGreaterThan(0);
  });

  test('stances only appear where there is more than one to switch between', () => {
    const bad = entries.filter(([, d]) => d.stances && d.stances.length < 2);
    expect(bad.map(([n]) => n)).toEqual([]);
  });
});

describe('general (unclassed) modded trinkets', () => {
  // `getTrinketImagePath` tests backer, then class-specific, then this list,
  // and only then falls through to the vanilla folder. A modded trinket sharing
  // a name with one of those would take over its picture, so the lists have to
  // stay disjoint.
  const taken = new Set([
    ...TRINKETS,
    ...BACKER_TRINKETS,
    ...Object.values(HERO_SPECIFIC_TRINKETS).flat(),
    ...Object.values(MODDED_HERO_CLASSES).flatMap((d) => d.classSpecificTrinkets || []),
  ]);

  test('no general trinket shadows a vanilla, backer or class trinket', () => {
    expect(MODDED_GENERAL_TRINKETS.filter((t) => taken.has(t))).toEqual([]);
  });

  test('the list has no repeats', () => {
    expect(new Set(MODDED_GENERAL_TRINKETS).size).toBe(MODDED_GENERAL_TRINKETS.length);
  });

  test('every one of them names the mod it came from', () => {
    // The image is filed as `<modId>_<name>.png`, so a missing mod id silently
    // asks for a file nothing writes.
    const orphan = MODDED_GENERAL_TRINKETS.filter((t) => !MODDED_GENERAL_TRINKET_MODS[t]);
    expect(orphan).toEqual([]);
    expect(Object.keys(MODDED_GENERAL_TRINKET_MODS).length).toBe(MODDED_GENERAL_TRINKETS.length);
  });

  test('their image path is namespaced by mod id', () => {
    const name = MODDED_GENERAL_TRINKETS[0];
    expect(getTrinketImagePath(name))
      .toContain(`/images/modded/trinkets/${MODDED_GENERAL_TRINKET_MODS[name]}_`);
  });
});

describe('class names', () => {
  test('a modded class never shadows a vanilla one', () => {
    // `HeroConfiguration` merges the two maps with the modded one last, so a
    // shared key would silently replace the vanilla hero.
    const clash = Object.keys(MODDED_HERO_CLASSES).filter((n) => HERO_CLASSES[n]);
    expect(clash).toEqual([]);
  });
});
